<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Business extends Model {protected $guarded=[]; public function branches(){return $this->hasMany(Branch::class);} public function getBillingSettings(){$settings=Setting::where('group','billing')->where('key','business_'.$this->id)->first();return $settings?$settings->value:$this->getDefaultBillingSettings();} public function getDefaultBillingSettings(){return ['company_name'=>'AutoCare Pro','address'=>'','phone'=>'','email'=>'','website'=>'','tax_id'=>'','invoice_prefix'=>'INV-','receipt_prefix'=>'REC-','footer_text'=>'Thank you for your business!','terms_conditions'=>'Payment due upon receipt. Valid for 30 days.','logo_path'=>'','reception_background_image'=>'','background_type'=>'image','background_color'=>'','custom_background_color'=>'','a4_enabled'=>true,'thermal_enabled'=>true,'default_format'=>'a4'];} public function saveBillingSettings(array $settings){Setting::updateOrCreate(['group'=>'billing','key'=>'business_'.$this->id],['value'=>$settings]);}}
